import React, { useState, useRef, useEffect } from 'react';
import './App.css';
import { Document, Packer, Paragraph, TextRun } from 'docx';

// API configuration
const API_BASE_URL = process.env.REACT_APP_API_URL || 'https://transcriber-ariel-f590de442515.herokuapp.com/api';

interface NetworkStatus {
  dns: boolean;
  http: boolean;
  https: boolean;
  assemblyai: boolean;
  iverit: boolean;
  overall: boolean;
}

interface ServicesAvailable {
  assemblyai: boolean;
  iverit: boolean;
}

interface RecordingStatus {
  filename?: string;
  local_save?: boolean;
  cloud_transcription?: 'pending' | 'success' | 'failed';
  text?: string;
  transcription_source?: string;
  retry_available?: boolean;
  error?: string;
}

function App() {
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [transcription, setTranscription] = useState('');
  const [error, setError] = useState('');
  const [audioBlob, setAudioBlob] = useState<Blob | null>(null);
  const [selectedService, setSelectedService] = useState('assemblyai');
  const [networkStatus, setNetworkStatus] = useState<NetworkStatus | null>(null);
  const [servicesAvailable, setServicesAvailable] = useState<ServicesAvailable | null>(null);
  const [recordingStatus, setRecordingStatus] = useState<RecordingStatus | null>(null);
  const [isCheckingNetwork, setIsCheckingNetwork] = useState(false);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);

  // Check network status on component mount
  useEffect(() => {
    checkNetworkStatus();
  }, []);

  const checkNetworkStatus = async () => {
    try {
      setIsCheckingNetwork(true);
      const response = await fetch(`${API_BASE_URL}/network-status`);
      const data = await response.json();
      
      if (data.status === 'success') {
        setNetworkStatus(data.network_status);
        setServicesAvailable(data.services_available);
      }
    } catch (error) {
      console.error('Failed to check network status:', error);
    } finally {
      setIsCheckingNetwork(false);
    }
  };

  const generateWordDocument = (text: string) => {
    const doc = new Document({
      sections: [{
        properties: {},
        children: [
          new Paragraph({
            children: [
              new TextRun(text),
            ],
          }),
        ],
      }],
    });

    Packer.toBlob(doc).then((blob) => {
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'transcription.docx';
      a.click();
      window.URL.revokeObjectURL(url);
    });
  };



  const downloadAudioAsWAV = async (blob: Blob) => {
    try {
      if (blob.size === 0) {
        console.error('Audio blob is empty');
        return;
      }
      
      console.log('Downloading audio file, size:', blob.size, 'bytes');
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'recording.wav';
      a.click();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      console.error('Failed to download audio:', error);
    }
  };

  const retryTranscription = async (filename: string) => {
    try {
      setIsProcessing(true);
      setError('');
      
      const response = await fetch(`${API_BASE_URL}/retry-transcription/${filename}`, {
        method: 'POST',
      });
      
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.message || 'Failed to retry transcription');
      }
      
      const result = await response.json();
      
      if (result.status === 'success') {
        setTranscription(result.text);
        generateWordDocument(result.text);
        setRecordingStatus(prev => ({
          ...prev,
          cloud_transcription: 'success',
          text: result.text,
          transcription_source: result.transcription_source
        }));
      } else {
        throw new Error(result.message || 'Retry failed');
      }
    } catch (err) {
      const error = err as Error;
      console.error('Retry error:', error);
      setError(`Retry failed: ${error.message}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleRecord = async () => {
    try {
      if (isRecording) {
        // Stop recording
        if (mediaRecorderRef.current) {
          mediaRecorderRef.current.stop();
          mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
          setIsRecording(false);
        }
      } else {
        // Start recording
        setError('');
        setTranscription('');
        setRecordingStatus(null);
        
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        const mediaRecorder = new MediaRecorder(stream);
        mediaRecorderRef.current = mediaRecorder;
        
        const audioChunks: BlobPart[] = [];
        
        mediaRecorder.ondataavailable = (event) => {
          if (event.data.size > 0) {
            audioChunks.push(event.data);
          }
        };
        
        mediaRecorder.onstop = async () => {
          try {
            setIsRecording(false);
            setIsProcessing(true);
            setError('');
            
            const audioBlob = new Blob(audioChunks, { type: 'audio/wav' });
            console.log('Audio blob created, size:', audioBlob.size, 'bytes, chunks:', audioChunks.length);
            setAudioBlob(audioBlob);
            
            // Use the new local-first recording endpoint
            const formData = new FormData();
            formData.append('file', audioBlob, 'recording.wav');
            
            const response = await fetch(`${API_BASE_URL}/record-and-transcribe`, {
              method: 'POST',
              body: formData,
            });
            
            if (!response.ok) {
              const errorData = await response.json().catch(() => ({}));
              throw new Error(errorData.message || 'Failed to save and transcribe audio');
            }
            
            const result = await response.json();
            setRecordingStatus(result);
            
            if (result.status === 'success') {
              // Always save locally first
              console.log('Recording saved locally:', result.filename);
              
              if (result.cloud_transcription === 'success' && result.text) {
                setTranscription(result.text);
                generateWordDocument(result.text);
                downloadAudioAsWAV(audioBlob);
              } else if (result.cloud_transcription === 'failed') {
                setError('הקלטה נשמרה לוקאלית. תמלול בענן נכשל - נסה שוב מאוחר יותר.');
                // Still download the audio file
                downloadAudioAsWAV(audioBlob);
              }
            } else {
              throw new Error(result.message || 'Recording failed');
            }
          } catch (err) {
            const error = err as Error;
            console.error('Recording error:', error);
            setError(`Error: ${error.message}`);
          } finally {
            setIsProcessing(false);
            mediaRecorderRef.current = null;
          }
        };
        
        mediaRecorder.start();
        setIsRecording(true);
        setTranscription('');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
      console.error('Error:', err);
    }
  };

  const handleDownload = async () => {
    if (transcription) {
      const doc = new Document({
        sections: [{
          properties: {},
          children: [
            new Paragraph({
              children: [
                new TextRun(transcription),
              ],
            }),
          ],
        }],
      });

      Packer.toBlob(doc).then((blob) => {
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = "transcription.docx";
        a.click();
        window.URL.revokeObjectURL(url);
      });
    }
  };

  const getNetworkStatusText = () => {
    if (isCheckingNetwork) return 'בודק חיבור לרשת...';
    if (!networkStatus) return 'לא ידוע';
    
    if (networkStatus.overall) {
      return 'מחובר לאינטרנט';
    } else {
      return 'אין חיבור לאינטרנט';
    }
  };

  const getServiceStatusText = () => {
    if (!servicesAvailable) return '';
    
    const available = [];
    if (servicesAvailable.assemblyai) available.push('AssemblyAI');
    if (servicesAvailable.iverit) available.push('iverit.ai');
    
    if (available.length === 0) return 'אין שירותי תמלול זמינים';
    return `שירותים זמינים: ${available.join(', ')}`;
  };

  return (
    <div className="App">
      <header className="App-header">
        <h1>ה-מתורגמן</h1>
        
        {/* Network Status */}
        <div className="network-status">
          <div className="status-item">
            <span className="status-label">חיבור לרשת:</span>
            <span className={`status-value ${networkStatus?.overall ? 'connected' : 'disconnected'}`}>
              {getNetworkStatusText()}
            </span>
          </div>
          <div className="status-item">
            <span className="status-label">שירותי תמלול:</span>
            <span className="status-value">{getServiceStatusText()}</span>
          </div>
          <button 
            onClick={checkNetworkStatus} 
            className="refresh-button"
            disabled={isCheckingNetwork}
          >
            {isCheckingNetwork ? 'בודק...' : 'רענן'}
          </button>
        </div>
        
        <div className="service-selector">
          <label htmlFor="service-select">בחר שירות תמלול:</label>
          <select 
            id="service-select"
            value={selectedService}
            onChange={(e) => setSelectedService(e.target.value)}
            disabled={isRecording || isProcessing}
          >
            <option value="assemblyai">AssemblyAI (מומלץ)</option>
            <option value="iverit">iverit.ai</option>
          </select>
        </div>
        
        <div className="status">
          {isRecording ? (
            <div className="recording-indicator">
              <div className="wave-container">
                <div className="wave wave1"></div>
                <div className="wave wave2"></div>
                <div className="wave wave3"></div>
                <div className="wave wave4"></div>
                <div className="wave wave5"></div>
              </div>
              <span>מקליט...</span>
            </div>
          ) : isProcessing ? (
            <div className="processing-indicator">
              <div className="spinner"></div>
              <span>מעבד תמלול...</span>
            </div>
          ) : (
            <p>לחץ על הכפתור למטה כדי להתחיל להקליט</p>
          )}
        </div>

        {/* Recording Status */}
        {recordingStatus && (
          <div className="recording-status">
            <h3>סטטוס הקלטה:</h3>
            <div className="status-details">
              <div className="status-item">
                <span>שמירה לוקאלית:</span>
                <span className={recordingStatus.local_save ? 'success' : 'error'}>
                  {recordingStatus.local_save ? '✅ הצליחה' : '❌ נכשלה'}
                </span>
              </div>
              <div className="status-item">
                <span>תמלול בענן:</span>
                <span className={
                  recordingStatus.cloud_transcription === 'success' ? 'success' : 
                  recordingStatus.cloud_transcription === 'failed' ? 'error' : 'pending'
                }>
                  {recordingStatus.cloud_transcription === 'success' ? '✅ הצליח' :
                   recordingStatus.cloud_transcription === 'failed' ? '❌ נכשל' : '⏳ ממתין'}
                </span>
              </div>
              {recordingStatus.filename && (
                <div className="status-item">
                  <span>שם קובץ:</span>
                  <span>{recordingStatus.filename}</span>
                </div>
              )}
              {recordingStatus.retry_available && (
                <button 
                  onClick={() => recordingStatus.filename && retryTranscription(recordingStatus.filename)}
                  className="retry-button"
                  disabled={isProcessing}
                >
                  נסה שוב תמלול
                </button>
              )}
            </div>
          </div>
        )}
        
        <button 
          onClick={handleRecord}
          className={`record-button ${isRecording ? 'recording' : ''} ${isProcessing ? 'processing' : ''}`}
          disabled={!navigator.mediaDevices || isProcessing}
          title={!navigator.mediaDevices ? 'גישה למיקרופון לא זמינה' : ''}
        >
          {isRecording ? 'עצור הקלטה' : isProcessing ? 'מעבד...' : 'התחל הקלטה'}
        </button>
        
        {error && (
          <div className="error-message">
            <h3>שגיאה:</h3>
            <p>{error}</p>
            <button onClick={() => setError('')} className="dismiss-button">
              סגור
            </button>
          </div>
        )}
        
        {transcription && (
          <div className="transcription-container">
            <h2>תמלול:</h2>
            <div className="transcription-text">
              {transcription || <em>אין תמלול זמין עדיין. התחל לדבר...</em>}
            </div>
            <div className="download-buttons">
              <button 
                onClick={handleDownload} 
                className="download-button"
                disabled={!transcription}
              >
                הורד כקובץ Word
              </button>
              <button 
                onClick={() => downloadAudioAsWAV(audioBlob!)} 
                className="download-button audio-download"
                disabled={!audioBlob}
              >
                הורד קובץ אודיו
              </button>
            </div>
          </div>
        )}
      </header>
    </div>
  );
}

export default App;
